// Foto de cada usuário no lugar da inicial, em todos os lugares onde o nome aparece.
const USER_AVATAR: Record<string, string> = {
  Johnnathan: johnnathanAvatar,
  Emanuel: emanuelAvatar,
};
function Avatar({ name, className }: { name: string; className: string }) {
  const src = USER_AVATAR[name];
  if (!src) {
    return (
      <span className={`${className} flex items-center justify-center rounded-full bg-slate-200 text-xs font-bold`}>
        {name ? name[0] : "○"}
      </span>
    );
  }
  return <img src={src} alt={name} className={`${className} rounded-full object-cover`} />;
}
