// Lista de cores própria, em vez de <select> nativo: o seletor do navegador
// mostra as opções sem cor, só o valor selecionado ficava colorido.
// Aqui cada opção já nasce com a sua cor de fundo.
function ColorDropdown({
  value,
  options,
  colors,
  onChange,
  ariaLabel,
  buttonClassName,
}: {
  value: string;
  options: string[];
  colors: Record<string, string>;
  onChange: (value: string) => void;
  ariaLabel: string;
  buttonClassName: string;
}) {
  const [open, setOpen] = useState(false);
  const [rect, setRect] = useState<DOMRect | null>(null);
  const btnRef = useRef<HTMLButtonElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const close = (e: MouseEvent) => {
      if (btnRef.current?.contains(e.target as Node)) return;
      if (menuRef.current?.contains(e.target as Node)) return;
      setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    document.addEventListener("mousedown", close);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("mousedown", close);
      document.removeEventListener("keydown", onKey);
    };
  }, [open ]);

  const menuHeight = options.length * 36;
  const top = rect
    ? rect.bottom + menuHeight > window.innerHeight
      ? Math.max(8, rect.top - menuHeight - 2)
      : rect.bottom + 2
    : 0;

  return (
    <>
      <button
        ref={btnRef}
        onClick={() => {
          if (!open && btnRef.current) setRect(btnRef.current.getBoundingClientRect());
          setOpen((v) => !v);
        }}
        aria-label={ariaLabel}
        className={buttonClassName}
        style={{ backgroundColor: colors[value] }}
      >
        {value} ▾
      </button>
      {open && rect && (
        <div
          ref={menuRef}
          className="fixed z-[100] overflow-hidden rounded-md shadow-lg"
          style={{ top, left: rect.left, width: Math.max(rect.width, 150) }}
        >
          {options.map((opt) => (
            <button
              key={opt}
              onClick={() => {
                onChange(opt);
                setOpen(false);
              }}
              className="block w-full px-3 py-2 text-center text-sm font-medium text-white hover:opacity-90"
              style={{ backgroundColor: colors[opt] }}
            >
              {opt}
            </button>
          ))}
        </div>
      )}
    </>
  );
}

// Logo Life Hotéis (imagem enviada pelo usuário, embutida em base64 porque o push não aceita binários).
const LIFE_LOGO = "data:image/png;base64,";
function LifeLogo() {
  return <img src={LIFE_LOGO} alt="Life Hotéis" className="h-10 w-auto shrink-0" />;
}

function newId() {
  if (typeof crypto !== "undefined" && "randomUUID" in crypto) return crypto.randomUUID();
  return `id-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

function newTask(title = "Nova tarefa"): Task {
  return {
    id: newId(),
    title,
    owner: "",
    status: "A fazer",
    priority: "Média",
    due: "",
    notes: "",
  };
}

